records=[]
for n,body in data.items():
 body+='\n\n'+common+'\n'
 p=Path(f'/tmp/tuldok-pr{n}-final-description.md');p.write_text(body)
 request=Path(f'/tmp/tuldok-pr{n}-description-request.json');request.write_text(json.dumps({'body':body}))
 result=json.loads(subprocess.check_output(['gh','api','--method','PATCH',f'repos/MrScripty/Tuldok/pulls/{n}','--input',str(request)]))
 assert result['body']==body
 records.append({'pr':n,'head':result['head']['sha'],'body_file':str(p),'confirmed':True})
Path('/tmp/tuldok-remaining-final-description-publication.json').write_text(json.dumps({'observed_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'records':records},indent=2)+'\n')
print(json.dumps(records))
